// ---- runtime (from tools/eyes-runtime.js) ----------------------------------
// An eye is two colours: --eye-i (the iris, red in the artwork) and --eye-k
// (the ink, black in the artwork). Normal: black iris, accent ink, the 4N look.
// Inverted: accent iris, black ink, like the tray's own eye.

const KEY = 'eye';
export const DEFAULT_EYE = { id: 'sharingan', invert: false };

export function getEye() {
  try {
    const v = JSON.parse(localStorage.getItem(KEY));
    if (v && EYES.some((e) => e.id === v.id)) return { id: v.id, invert: !!v.invert };
  } catch {
    // nothing saved, or storage blocked
  }
  return { ...DEFAULT_EYE };
}

let n = 0;
/**
 * The eye as an inline SVG string; colours follow `color` (currentColor).
 * With `color`, the colours are baked in as plain attributes and there is no
 * style attribute at all: for standalone files (reports) that must not depend
 * on the page's CSS or carry inline styles.
 */
export function eyeSvg({ id, invert } = getEye(), { size = 30, cls = 'app-logo', label = '', color = '' } = {}) {
  const e = EYES.find((x) => x.id === id) || EYES[0];
  const a11y = label ? `role="img" aria-label="${label}"` : 'aria-hidden="true"';
  let body = e.svg.replaceAll('{p}', `eye${++n}-`);
  let vars = ` style="${invert ? '--eye-i:currentColor;--eye-k:#000' : '--eye-i:#000;--eye-k:currentColor'}"`;
  if (color) {
    const [i, k] = invert ? [color, '#000'] : ['#000', color];
    body = body.replace(/ style="([^"]*)"/g, (_, css) => css.split(';').filter(Boolean)
      .map((d) => { const [p, v] = d.split(':'); return ` ${p}="${v.replace('var(--eye-i)', i).replace('var(--eye-k)', k)}"`; }).join(''));
    vars = '';
  }
  return `<svg class="${cls}" viewBox="${e.vb}" width="${size}" height="${size}"${vars} ${a11y}>${body}</svg>`;
}

/** Fill every <… data-eye="SIZE"> under root with the chosen eye (data-eye-class sets the svg class). */
export function mountEyes(root = document) {
  const pref = getEye();
  for (const el of root.querySelectorAll('[data-eye]')) {
    el.innerHTML = eyeSvg(pref, { size: +el.dataset.eye || 30, cls: el.dataset.eyeClass || 'app-logo' });
  }
}

export function setEye(pref) {
  const v = { ...getEye(), ...pref };
  try {
    if (v.id === DEFAULT_EYE.id && !v.invert) localStorage.removeItem(KEY);
    else localStorage.setItem(KEY, JSON.stringify(v));
  } catch {
    // storage blocked: the choice still applies for this visit
  }
  mountEyes();
  dispatchEvent(new CustomEvent('eyechange', { detail: v }));
  return v;
}
// Another tab changed it.
globalThis.addEventListener?.('storage', (e) => {
  if (e.key === KEY) {
    mountEyes();
    dispatchEvent(new CustomEvent('eyechange', { detail: getEye() }));
  }
});

const CSS = `.eye-picker{display:flex;flex-wrap:wrap;align-items:center;gap:10px 14px}
.eye-drop[open]{flex-basis:100%}
.eye-drop>summary{display:inline-flex;align-items:center;gap:8px;padding:4px 10px 4px 5px;cursor:pointer;list-style:none;
  background:var(--bg-deep,#0d1117);border:1px solid var(--border,#30363d);border-radius:8px;color:var(--accent,#9fef00)}
.eye-drop>summary::-webkit-details-marker{display:none}
.eye-drop>summary::after{content:"";width:6px;height:6px;margin-top:-3px;border:solid var(--text-secondary,#8b949e);border-width:0 1.5px 1.5px 0;transform:rotate(45deg);transition:transform .15s}
.eye-drop[open]>summary::after{transform:rotate(-135deg);margin-top:3px}
.eye-drop>summary:hover,.eye-drop[open]>summary{border-color:var(--accent,#9fef00)}
.eye-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(44px,1fr));gap:5px;margin-top:6px;padding:6px;
  background:var(--bg-deep,#0d1117);border:1px solid var(--border,#30363d);border-radius:8px}
.eye-grid button{display:grid;place-items:center;padding:4px;cursor:pointer;background:none;
  border:1px solid transparent;border-radius:6px;color:var(--accent,#9fef00)}
.eye-grid button:hover{border-color:var(--text-muted,#6e7681)}
.eye-grid button[aria-pressed=true]{border-color:var(--accent,#9fef00);background:color-mix(in srgb,var(--accent,#9fef00) 10%,transparent)}
/* doubled class: beats an app's own "form label" / "form input" rules */
.eye-invert.eye-invert{display:inline-flex;align-items:center;gap:8px;margin:0;cursor:pointer;color:var(--text-secondary,#8b949e);font-size:12.5px;font-weight:500}
.eye-invert.eye-invert input{appearance:auto;accent-color:var(--accent,#9fef00);width:15px;height:15px;margin:0;padding:0;border:0;background:none;box-shadow:none}
.eye-pop{position:fixed;z-index:1000;width:min(300px,calc(100vw - 16px));max-height:calc(100vh - 16px);overflow:auto;padding:10px;background:var(--bg-elevated,#21262d);
  border:1px solid var(--accent-border,rgba(159,239,0,.3));border-radius:12px;box-shadow:0 18px 44px rgba(0,0,0,.55);animation:eye-pop .14s ease-out}
.eye-pop .eye-drop>summary{display:none}
.eye-pop .eye-grid{margin-top:0}
@keyframes eye-pop{from{opacity:0;transform:translateY(-4px) scale(.98)}}
[data-eye-egg]{user-select:none;-webkit-user-select:none}
/* Only the pattern turns; the iris and rim stand still. Speed: --eye-spin on the svg.
   The pivot is set on each eye (transform-origin in user units): with transform-box
   view-box, a percentage is measured from 0,0, not from the viewBox corner. */
.eye-spin{transform-box:view-box;animation:eye-spin var(--eye-spin,14s) linear infinite}
@keyframes eye-spin{to{transform:rotate(360deg)}}
.eye-thumb .eye-spin{animation:none}
@media (prefers-reduced-motion:reduce){.eye-spin{animation:none}}
.eye-theme{display:flex;align-items:center;gap:8px;margin-top:10px;padding-top:10px;border-top:1px solid var(--border,#30363d);
  color:var(--text-secondary,#8b949e);font:500 12.5px var(--sans,'Inter',sans-serif)}
.eye-theme label{flex:1;margin:0;font:inherit;color:inherit}
/* by id: some apps style every text-like input with long :not() chains */
#eye-theme-colour{appearance:auto;width:36px;height:26px;min-width:0;padding:0;margin:0;cursor:pointer;
  background:none;border:1px solid var(--border,#30363d);border-radius:4px;box-shadow:none}
.eye-theme.eye-theme button{padding:4px 10px;margin:0;cursor:pointer;background:var(--bg-surface,#30363d);color:var(--text,#e6edf3);
  border:1px solid var(--border,#30363d);border-radius:6px;font:inherit;width:auto}`;

/**
 * A dropdown of every eye (no names on show: each has its name as a tooltip
 * and for screen readers) plus an Invert switch, wired to setEye.
 */
function addCss() {
  if (document.getElementById('eye-picker-css')) return;
  const st = document.createElement('style');
  st.id = 'eye-picker-css';
  st.textContent = CSS;
  document.head.append(st);
}

export function eyePicker(container, { open = false } = {}) {
  addCss();
  const pref = getEye();
  const thumb = (id, invert, size = 32) => eyeSvg({ id, invert }, { size, cls: 'eye-thumb' });
  const name = (id) => (EYES.find((e) => e.id === id) || EYES[0]).name;
  container.innerHTML = `<div class="eye-picker"><details class="eye-drop"${open ? ' open' : ''}>
      <summary title="Logo: ${name(pref.id)}" aria-label="Logo: ${name(pref.id)}">${thumb(pref.id, pref.invert, 28)}</summary>
      <div class="eye-grid" role="group" aria-label="Logo">${EYES.map((e) =>
        `<button type="button" data-id="${e.id}" aria-pressed="${e.id === pref.id}" title="${e.name}" aria-label="${e.name}">${thumb(e.id, pref.invert)}</button>`).join('')}</div>
    </details>
    <label class="eye-invert"><input type="checkbox"${pref.invert ? ' checked' : ''}> Invert colours</label></div>`;
  // Updated in place, never rebuilt: a menu that closes on "click outside"
  // would take a clicked-then-removed button for an outside click.
  const drop = container.querySelector('details');
  const summary = drop.firstElementChild;
  const buttons = [...container.querySelectorAll('[data-id]')];
  let shown = pref.invert;
  const sync = () => {
    if (!container.isConnected) return removeEventListener('eyechange', sync); // the menu was closed
    const p = getEye();
    summary.firstElementChild.outerHTML = thumb(p.id, p.invert, 28);
    summary.title = `Logo: ${name(p.id)}`;
    summary.setAttribute('aria-label', summary.title);
    for (const b of buttons) {
      b.setAttribute('aria-pressed', String(b.dataset.id === p.id));
      // thumbnails redrawn only when the colours flip, never under a click on an eye
      if (p.invert !== shown) b.firstElementChild.outerHTML = thumb(b.dataset.id, p.invert);
    }
    shown = p.invert;
    container.querySelector('.eye-invert input').checked = p.invert;
  };
  for (const b of buttons) b.onclick = () => { setEye({ id: b.dataset.id }); drop.open = false; };
  container.querySelector('.eye-invert input').onchange = (ev) => setEye({ invert: ev.target.checked });
  // a press anywhere else folds the list away (capture phase: an app that
  // stops its own clicks from bubbling cannot keep it open)
  const away = (ev) => {
    if (!container.isConnected) return document.removeEventListener('pointerdown', away, true);
    if (drop.open && !container.contains(ev.target)) drop.open = false;
  };
  document.addEventListener('pointerdown', away, true);
  addEventListener('eyechange', sync);
  return container;
}

// ---- Easter egg -----------------------------------------------------------
// The picker is not in any menu: click the logo (any element marked
// data-eye-egg) five times within 1.5 s and it opens beside it. A pick, a
// click elsewhere or Escape closes it.
let taps = [];
function openEgg(anchor) {
  document.querySelector('.eye-pop')?.remove();
  const pop = document.createElement('div');
  pop.className = 'eye-pop';
  pop.setAttribute('role', 'dialog');
  pop.setAttribute('aria-label', 'Logo');
  document.body.append(pop);
  eyePicker(pop, { open: true });
  const row = document.createElement('div');
  row.className = 'eye-theme';
  row.innerHTML = '<label for="eye-theme-colour">Theme colour</label><input id="eye-theme-colour" type="color"><button type="button">Reset</button>';
  const pick = row.querySelector('input');
  pick.value = theme.get();
  pick.oninput = () => setAccent(pick.value);
  row.querySelector('button').onclick = () => { pick.value = theme.def; setAccent(theme.def); };
  pop.append(row);
  const r = anchor.getBoundingClientRect();
  // under the logo, but always inside the window (never above its top edge)
  pop.style.left = `${Math.max(8, Math.min(r.left, innerWidth - pop.offsetWidth - 8))}px`;
  pop.style.top = `${Math.max(8, Math.min(r.bottom + 8, innerHeight - pop.offsetHeight - 8))}px`;
  const close = () => { pop.remove(); removeEventListener('keydown', esc); };
  const esc = (e) => { if (e.key === 'Escape') close(); };
  pop.querySelector('details').addEventListener('toggle', (e) => { if (!e.target.open) close(); });
  addEventListener('keydown', esc);
}
if (globalThis.document) addCss();
globalThis.document?.addEventListener('click', (ev) => {
  const el = ev.target.closest?.('[data-eye-egg]');
  if (!el) return;
  const now = performance.now();
  taps = taps.filter((t) => now - t < 1500);
  taps.push(now);
  if (taps.length >= 5) {
    taps = [];
    openEgg(el);
  }
});

// ---- theme colour -----------------------------------------------------------
// The popup's colour row drives the app's accent. An app with its own accent
// setting registers it with registerAccent({ get, set, def }) so both stay in step;
// otherwise the colour is kept here: localStorage "accent-color", applied as
// --accent on <html> (the app's CSS derives everything else from it).
const ACCENT_KEY = 'accent-color';
const HEX = /^#[0-9a-f]{6}$/i;
let theme = {
  def: '#9fef00',
  get() {
    try {
      const v = localStorage.getItem(ACCENT_KEY);
      if (HEX.test(v || '')) return v.toLowerCase();
    } catch {
      // storage blocked
    }
    return this.def;
  },
  set(hex) {
    try {
      if (hex === this.def) localStorage.removeItem(ACCENT_KEY);
      else localStorage.setItem(ACCENT_KEY, hex);
    } catch {
      // storage blocked: the colour still applies for this visit
    }
    const st = document.documentElement.style;
    if (hex === this.def) st.removeProperty('--accent');
    else st.setProperty('--accent', hex);
  },
};
export function registerAccent(handler) {
  theme = { ...theme, ...handler };
}
export function setAccent(hex) {
  if (!HEX.test(hex)) return;
  theme.set(hex.toLowerCase());
  dispatchEvent(new CustomEvent('accentchange', { detail: hex.toLowerCase() }));
}
// A colour saved by the built-in store applies as soon as the page loads.
if (globalThis.document) {
  const saved = theme.get();
  if (saved !== theme.def) document.documentElement.style.setProperty('--accent', saved);
}
